mkdir qa && cat > qa/test_gaps.py <<'EOF'
import unittest

from hourglass.gaps import find_gaps
from hourglass.parsing import parse_span


def spans(*texts):
    return [parse_span(t) for t in texts]


class FindGapsTest(unittest.TestCase):
    def test_gap_in_middle(self):
        result = find_gaps(
            spans("09:00-12:00", "13:00-17:00"), parse_span("09:00-17:00")
        )
        self.assertEqual(result, ["gap 12:00-13:00 (60 min)"])

    def test_edges_and_empty(self):
        opening = parse_span("09:00-17:00")
        self.assertEqual(
            find_gaps(spans("10:00-16:00"), opening),
            ["gap 09:00-10:00 (60 min)", "gap 16:00-17:00 (60 min)"],
        )
        self.assertEqual(
            find_gaps([], opening), ["gap 09:00-17:00 (480 min)"]
        )

    def test_full_coverage(self):
        result = find_gaps(
            spans("09:00-13:00", "12:00-17:00"), parse_span("09:00-17:00")
        )
        self.assertEqual(result, [])

    def test_outside_opening_raises(self):
        with self.assertRaises(ValueError):
            find_gaps(spans("08:00-10:00"), parse_span("09:00-17:00"))


if __name__ == "__main__":
    unittest.main()
